import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Math, text, lists and loops","description":"Mapping Blockly and ioBroker blocks to native UGSo HA output.","frontmatter":{"title":"Math, text, lists and loops","description":"Mapping Blockly and ioBroker blocks to native UGSo HA output."},"headers":[],"relativePath":"en/projects/blocks-for-ha/collections.md","filePath":"en/projects/blocks-for-ha/collections.md","lastUpdated":1793126212000}'),n={name:"en/projects/blocks-for-ha/collections.md"};function r(o,t,l,d,p,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="math-text-lists-and-loops" tabindex="-1">Math, text, lists and loops <a class="header-anchor" href="#math-text-lists-and-loops" aria-label="Permalink to &quot;Math, text, lists and loops&quot;">​</a></h1><p><strong>Since 0.1.14:</strong> 37 additional block types, <strong>105</strong> in total. <a href="./blocks">All blocks with actual editor images</a>. The two supplied text screenshots show the same category and are considered once. These are original HA-YAML/Jinja generators; ioBroker JavaScript is not executed.</p><h2 id="comparison-with-upstream" tabindex="-1">Comparison with upstream <a class="header-anchor" href="#comparison-with-upstream" aria-label="Permalink to &quot;Comparison with upstream&quot;">​</a></h2><p>References: original Blockly <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/loops.ts" target="_blank" rel="noreferrer">loops</a>, <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/math.ts" target="_blank" rel="noreferrer">math</a>, <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/text.ts" target="_blank" rel="noreferrer">text</a> and <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/lists.ts" target="_blank" rel="noreferrer">lists</a>. ioBroker additions for <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_number.ts" target="_blank" rel="noreferrer">decimal precision</a> and <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_text.ts" target="_blank" rel="noreferrer">text</a> were also reviewed. The target output follows <a href="https://www.home-assistant.io/template-functions/" target="_blank" rel="noreferrer">HA template functions</a> and <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">HA script actions</a>.</p><table tabindex="0"><thead><tr><th>Area / upstream</th><th>UGSo implementation</th><th>Differences / pending variants</th></tr></thead><tbody><tr><td>Repeat, while/until</td><td>Existing native HA repeat blocks</td><td>While tests before, until after each iteration.</td></tr><tr><td>Count from/to/step</td><td>New counting block</td><td>Fixed integer bounds, step magnitude, inclusive end on the step grid, automatically ascending/descending, at most 10000 values. Dynamic/fractional bounds remain pending.</td></tr><tr><td>For each list item</td><td>Additional named-variable block</td><td>Assigns the variable from repeat.item before each body.</td></tr><tr><td>break / continue</td><td>Pending</td><td>HA Stop ends the entire run. Local control flow needs a separate model and nested-loop tests.</td></tr><tr><td>Number, variable change</td><td>Already available</td><td>Initialize variables first; increment requires numbers.</td></tr><tr><td>Arithmetic, single-number math, trig, constants</td><td>New Math category</td><td>Root, abs, negation, ln/log10, powers; angles in degrees. Infinity is not offered.</td></tr><tr><td>Number properties</td><td>Even/odd/whole/positive/negative/divisible</td><td>Prime test remains pending.</td></tr><tr><td>Rounding / ioBroker decimal places</td><td>Shared block: normal/up/down, 0–10 places</td><td>HA/Jinja rounding rather than JavaScript Math.round.</td></tr><tr><td>Math on list</td><td>Sum, min/max, mean, median, random item</td><td>Blockly mode as a list of all most frequent values and standard deviation remain pending; HA statistical_mode alone would not have the same meaning.</td></tr><tr><td>Modulo, constrain, random</td><td>New value blocks</td><td>Negative modulo follows Jinja. Integer random has inclusive bounds and at most 10000 choices; fractions use increments of 0.00001.</td></tr><tr><td>atan2</td><td>Additional original Blockly operation</td><td>Not visible in supplied math screenshots; not presented as an ioBroker deficiency.</td></tr><tr><td>Single/multiline text</td><td>Existing text block</td><td>Original multiline field.</td></tr><tr><td>Newline, join, append</td><td>New text blocks</td><td>LF/CRLF/CR; join with gear/+−; append assigns a new text variable value.</td></tr><tr><td>Text length/empty/contains/find/character/substring</td><td>New text blocks</td><td>1-based indices, missing search returns 0. Inclusive substring bounds from start; substring bounds from end remain pending.</td></tr><tr><td>Case, trim, count, replace, reverse</td><td>New text blocks</td><td>Literal matching rather than regex, Unicode/Python rules. Reverse is also in original Blockly.</td></tr><tr><td>print / prompt</td><td>Existing log action; prompt pending</td><td>A browser prompt would not be an input dialog for an automation running later in HA.</td></tr><tr><td>Empty list / create with items</td><td>Existing list block with 0–100 inputs</td><td>Gear/+− changes the items.</td></tr><tr><td>Repeat item, length/empty, index, get, sublist</td><td>Existing and new list blocks</td><td>Get from start/end/first/last/random. Inclusive sublist bounds from start.</td></tr><tr><td>Set/insert/remove list item</td><td>New action blocks</td><td>New list assigned to a variable; other variables are not mutated. Combined get-and-remove value block, edits from end and random removal remain pending.</td></tr><tr><td>Split/join, sort, reverse</td><td>New list blocks</td><td>Numeric/text/case-insensitive sorting; original stays unchanged.</td></tr></tbody></table><h2 id="controls-and-runtime-values" tabindex="-1">Controls and runtime values <a class="header-anchor" href="#controls-and-runtime-values" aria-label="Permalink to &quot;Controls and runtime values&quot;">​</a></h2><p>Menu, pale flyout and colored blocks remain distinct; <strong>Search stays last</strong>. Math is blue-purple, text dark green, lists purple and loops green. Values connect to variables, comparisons, templates and runtime pauses. Fixed numeric trigger limits still accept number literals rather than calculated templates.</p><p>Text join has 0–100 inputs. Create variable remains in the Variables category; text/list modification blocks select that variable. Initialize it with the matching type before appending/modifying. Explicitly convert HA state strings to numbers when needed. Invalid types or fractional indices cause template errors rather than silent conversion.</p><p>Index <strong>1</strong> means the first item; from end, 1 means the last. Out-of-range reads return empty text or null; out-of-range list edits leave the list unchanged. Inserting at length+1 appends. A substring/sublist with start above end or below 1 returns empty. An end beyond length is truncated.</p><p>Example: count <code>i</code> from 1 to 5 by 2, with a template value containing <code>i</code> in the body log action:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">repeat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      for_each</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ range(1, 6, 2) | list }}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      sequence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">variables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ repeat.item }}&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">system_log.write</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ i }}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>This produces 1, 3, 5. Use distinct variables in nested loops; repeat.item always refers to the innermost iteration. Store random/time-dependent expressions in a variable first if the same value is needed in multiple places: nested templates may evaluate inputs more than once.</p><h2 id="javascript-differences-and-persistence" tabindex="-1">JavaScript differences and persistence <a class="header-anchor" href="#javascript-differences-and-persistence" aria-label="Permalink to &quot;JavaScript differences and persistence&quot;">​</a></h2><ul><li>At zero decimal places, 2.5 rounds to 2 and 3.5 to 4; JavaScript Math.round differs. Up/down use ceil/floor.</li><li>Negative modulo: −9 modulo 2 produces 1. Angles convert between degrees and HA radians.</li><li>Text operations count Unicode code points. An emoji may use two JavaScript UTF-16 units; combining characters/graphemes may still span several code points. Title case and trim use Python/Jinja rules.</li><li>Empty search text explicitly returns 0 for count and leaves replace unchanged. Matches do not overlap. Searching is literal and case-sensitive.</li><li>Empty list: sum 0; other math aggregates and random item null. Numeric aggregation/sorting requires actual numbers rather than Boolean/text values. Python equality may consider 1 and true equal, unlike JavaScript reference equality.</li><li>List modification uses copies, slices and native HA variable assignment, without list.append/pop mutation in the immutable sandbox.</li></ul><p>Project JSON preserves shapes, fields, dropdowns, order and connected items. YAML import preserves meaning, reopening complex expressions as general templates and counting loops as native For-each with a variable assignment. YAML does not contain enough information to reconstruct original Blockly shapes uniquely.</p><p>Verified: all 37 new types through JSON/YAML, edge cases, immutable Jinja sandbox with HA math helpers, categories and text + button in the browser, app/docs builds and Docker preview. Execution against a real Home Assistant instance remains pending.</p>`,16)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
